<!DOCTYPE html>
<html lang="zh-CN">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>算账计算器 - 交互原型</title>
<style>
*{margin:0;padding:0;box-sizing:border-box;}
body{font-family:-apple-system,"Segoe UI","Microsoft YaHei",sans-serif;background:#f0f2f5;display:flex;justify-content:center;align-items:center;min-height:100vh;color:#333;}
.app{display:flex;width:680px;max-width:98vw;height:500px;background:#fff;border-radius:16px;box-shadow:0 8px 32px rgba(0,0,0,.1);overflow:hidden;}
.calc-panel{flex:0 0 340px;display:flex;flex-direction:column;background:#fafbfc;border-right:1px solid #e8eaed;}
.display{padding:20px 20px 12px;text-align:right;min-height:100px;display:flex;flex-direction:column;justify-content:flex-end;}
.expr{font-size:14px;color:#888;min-height:22px;word-break:break-all;line-height:1.4;}
.result{font-size:36px;font-weight:600;color:#1a1a2e;margin-top:4px;letter-spacing:-.5px;overflow:hidden;text-overflow:ellipsis;}
.keys{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;padding:8px 12px 12px;flex:1;}
.key{border:none;border-radius:10px;font-size:18px;cursor:pointer;display:flex;align-items:center;justify-content:center;transition:all .12s;background:#fff;color:#333;box-shadow:0 1px 3px rgba(0,0,0,.08);font-weight:500;user-select:none;}
.key:hover{background:#f0f0f0;box-shadow:0 2px 6px rgba(0,0,0,.1);}
.key:active{transform:scale(.95);background:#e4e4e4;}
.key.op{background:#e8f0fe;color:#1a73e8;}
.key.op:hover{background:#d2e3fc;}
.key.op.active-op{background:#1a73e8;color:#fff;}
.key.eq{background:#1a73e8;color:#fff;font-size:22px;}
.key.eq:hover{background:#1557b0;}
.key.eq:active{background:#12458a;}
.key.fn{background:#f1f3f4;color:#5f6368;font-size:15px;}
.key.fn:hover{background:#e0e2e5;}
.key.zero{grid-column:span 2;}
.hist-panel{flex:1;display:flex;flex-direction:column;min-width:0;}
.hist-header{display:flex;align-items:center;justify-content:space-between;padding:16px 20px;border-bottom:1px solid #e8eaed;background:#fafbfc;}
.hist-header h3{font-size:15px;font-weight:600;color:#1a1a2e;display:flex;align-items:center;gap:6px;}
.hist-header h3::before{content:"📋";font-size:14px;}
.clear-btn{border:none;background:none;color:#1a73e8;font-size:13px;cursor:pointer;padding:4px 10px;border-radius:6px;font-weight:500;}
.clear-btn:hover{background:#e8f0fe;}
.hist-list{flex:1;overflow-y:auto;padding:8px 12px;}
.hist-list::-webkit-scrollbar{width:4px;}
.hist-list::-webkit-scrollbar-thumb{background:#ccc;border-radius:2px;}
.hist-item{padding:12px 14px;border-radius:10px;margin-bottom:6px;cursor:pointer;transition:all .15s;border:1.5px solid transparent;background:#f8f9fa;}
.hist-item:hover{background:#f0f4ff;border-color:#c5d7f7;}
.hist-item.active{background:#e8f0fe;border-color:#1a73e8;}
.hist-expr{font-size:13px;color:#666;margin-bottom:4px;word-break:break-all;}
.hist-result{font-size:20px;font-weight:600;color:#1a1a2e;}
.hist-time{font-size:11px;color:#aaa;margin-top:4px;}
.hist-steps{display:none;margin-top:8px;padding-top:8px;border-top:1px dashed #d0d7e2;}
.hist-item.expanded .hist-steps{display:block;}
.step{font-size:12px;color:#555;padding:3px 0;display:flex;align-items:center;gap:6px;}
.step::before{content:"";display:inline-block;width:6px;height:6px;border-radius:50%;background:#1a73e8;flex-shrink:0;}
