.tag{display:inline-block;font-size:10px;background:#e8f0fe;color:#1a73e8;padding:2px 6px;border-radius:4px;margin-left:6px;font-weight:500;}
</style>
</head>
<body>
<div class="app">
  <div class="calc-panel">
    <div class="display">
      <div class="expr" id="expr"></div>
      <div class="result" id="result">0</div>
    </div>
    <div class="keys" id="keys">
      <button class="key fn" data-v="C">AC</button>
      <button class="key fn" data-v="back">⌫</button>
      <button class="key fn" data-v="%">%</button>
      <button class="key op" data-v="÷">÷</button>
      <button class="key" data-v="7">7</button>
      <button class="key" data-v="8">8</button>
      <button class="key" data-v="9">9</button>
      <button class="key op" data-v="×">×</button>
      <button class="key" data-v="4">4</button>
      <button class="key" data-v="5">5</button>
      <button class="key" data-v="6">6</button>
      <button class="key op" data-v="-">−</button>
      <button class="key" data-v="1">1</button>
      <button class="key" data-v="2">2</button>
      <button class="key" data-v="3">3</button>
      <button class="key op" data-v="+">+</button>
      <button class="key zero" data-v="0">0</button>
      <button class="key" data-v=".">.</button>
      <button class="key eq" data-v="=">=</button>
    </div>
  </div>
  <div class="hist-panel">
    <div class="hist-header">
      <h3>计算记录</h3>
      <button class="clear-btn" id="clearHist">清空</button>
    </div>
    <div class="hist-list" id="histList">
      <div class="empty-state" id="emptyState"><span>🧮</span>点击按键开始算账<br><small style="color:#ccc">历史记录将显示在这里，可展开查看步骤</small></div>
    </div>
  </div>
</div>

<script>
(function(){
  const exprEl=document.getElementById('expr');
  const resEl=document.getElementById('result');
  const histList=document.getElementById('histList');
  const emptyState=document.getElementById('emptyState');
  let currentInput='0';
  let expression='';
  let justEvaluated=false;
  let history=[];
  let stepCounter=0;
  let currentSteps=[];

  // Mock calculation
  function mockCalc(expr){
    try{
      let e=expr.replace(/×/g,'*').replace(/÷/g,'/').replace(/−/g,'-');
      let r=Function('"use strict";return ('+e+')')();
      if(!isFinite(r))return 'Error';
      return parseFloat(r.toFixed(8)).toString();
    }catch(ex){return 'Error';}
  }

  function generateSteps(expr,result){
    let steps=[];
    let tokens=expr.match(/[\d.]+|[+\-×÷%]/g)||[];
    if(tokens.length<3){
      steps.push('输入表达式: '+expr);
      steps.push('得出结果: '+result);
      return steps;
    }
    // Simulate step-by-step for multi-operation expressions
    let running=tokens[0];
    steps.push('开始计算: '+tokens[0]);
    for(let i=1;i<tokens.length-1;i+=2){
      let op=tokens[i],num=tokens[i+1];
      if(!num)break;
      let partialExpr=running+' '+op+' '+num;
      let partialRes=mockCalc(partialExpr);
      steps.push(partialExpr+' = '+partialRes);
      running=partialRes;
    }
    steps.push('最终结果: '+result);
    return steps;
  }

  function formatTime(){
    let d=new Date();
    return d.getHours().toString().padStart(2,'0')+':'+d.getMinutes().toString().padStart(2,'0')+':'+d.getSeconds().toString().padStart(2,'0');
  }

  function updateDisplay(){
    exprEl.textContent=expression;
    resEl.textContent=currentInput;
  }

  function addHistory(expr,result,steps,time){
    emptyState.style.display='none';
    let item=document.createElement('div');
    item.className='hist-item';
    let stepsHtml=steps.map(s=>'<div class="step">'+s+'</div>').join('');
    item.innerHTML='<div class="hist-expr">'+expr+' =</div><div class="hist-result">'+result+(steps.length>2?'<span class="tag">多步</span>':'')+'</div><div class="hist-time">'+time+'</div><div class="hist-steps">'+stepsHtml+'</div>';
    item.addEventListener('click',function(){
      document.querySelectorAll('.hist-item').forEach(el=>el.classList.remove('expanded','active'));
      this.classList.toggle('expanded');
      this.classList.add('active');
      // Recall to display
      exprEl.textContent=expr+' =';
      resEl.textContent=result;
    });
    histList.insertBefore(item,histList.firstChild);
    history.push({expr,result,steps,time});
  }

  function clearActiveOp(){
    document.querySelectorAll('.key.op').forEach(k=>k.classList.remove('active-op'));
  }

  function setActiveOp(v){
    clearActiveOp();
    document.querySelectorAll('.key.op').forEach(k=>{if(k.dataset.v===v)k.classList.add('active-op');});
  }

  document.getElementById('keys').addEventListener('click',function(e){
    let btn=e.target.closest('.key');
    if(!btn)return;
    let v=btn.dataset.v;

    if(v==='C'){
      currentInput='0';expression='';justEvaluated=false;currentSteps=[];stepCounter=0;
      clearActiveOp();updateDisplay();return;
    }
    if(v==='back'){
      if(justEvaluated)return;
      if(currentInput.length>1){currentInput=currentInput.slice(0,-1);}else{currentInput='0';}
      updateDisplay();return;
    }

    if(['+','-','×','÷','%'].includes(v)){
      if(justEvaluated){
        expression=currentInput+' '+v+' ';
        justEvaluated=false;
      }else{
        if(expression&&currentInput!=='0'){
          // chain calc
          let fullExpr=expression+currentInput;
          let res=mockCalc(fullExpr);
          currentSteps.push(fullExpr+' = '+res);
          expression=res+' '+v+' ';
          currentInput='0';
        }else{
          expression=(currentInput==='0'?'0':currentInput)+' '+v+' ';
        }
      }
      currentInput='0';
      setActiveOp(v);
      updateDisplay();return;
    }

    if(v==='='){
      clearActiveOp();
      if(!expression)return;
      let fullExpr=expression+currentInput;
      let result=mockCalc(fullExpr);
      let steps=generateSteps(fullExpr,result);
      let time=formatTime();
      addHistory(fullExpr,result,steps,time);
      expression=fullExpr+' =';
      currentInput=result;
      justEvaluated=true;
      updateDisplay();return;
    }

    // Number or dot
    clearActiveOp();
    if(justEvaluated){
      currentInput=v==='.'?'0.':v;
      expression='';justEvaluated=false;
    }else{
      if(currentInput==='0'&&v!=='.'){currentInput=v;}
      else if(v==='.'&&currentInput.includes('.')){/* skip */}
      else{currentInput+=v;}
    }
    updateDisplay();
  });

  document.getElementById('clearHist').addEventListener('click',function(){
    histList.innerHTML='<div class="empty-state" id="emptyState"><span>🧮</span>点击按键开始算账<br><small style="color:#ccc">历史记录将显示在这里，可展开查看步骤</small></div>';
    history=[];
  });

  // Pre-populate some demo history
  setTimeout(()=>{
    let demos=[
      {expr:'128 × 3 + 50',result:'434',steps:['开始计算: 128','128 × 3 = 384','384 + 50 = 434','最终结果: 434'],time:'09:15:32'},
      {expr:'2580 ÷ 12',result:'215',steps:['输入表达式: 2580 ÷ 12','得出结果: 215'],time:'09:12:08'},
      {expr:'99.5 + 128 + 45.8',result:'273.3',steps:['开始计算: 99.5','99.5 + 128 = 227.5','227.5 + 45.8 = 273.3','最终结果: 273.3'],time:'09:08:45'}
    ];
    demos.forEach(d=>addHistory(d.expr,d.result,d.steps,d.time));
  },300);

  updateDisplay();
})();
</script>
</body>
</html>
