<body>
<div class="phone">
<div class="status-bar"><span>9:41</span><span>⚡ 100%</span></div>
<div class="header">
<h1>📒 Bookkeeping</h1>
<button class="clear-btn" onclick="clearAll()">CLEAR ALL</button>
</div>
<div class="tape-container" id="tape"></div>
<div class="display-area">
<div class="expression" id="expression"></div>
<div class="current-value" id="display">0</div>
</div>
<div class="buttons">
<button class="btn btn-func" onclick="inputClear()">AC</button>
<button class="btn btn-func" onclick="toggleSign()">+/−</button>
<button class="btn btn-func" onclick="inputPercent()">%</button>
<button class="btn btn-op" id="op-div" onclick="inputOp('÷')">÷</button>
<button class="btn btn-num" onclick="inputNum('7')">7</button>
<button class="btn btn-num" onclick="inputNum('8')">8</button>
<button class="btn btn-num" onclick="inputNum('9')">9</button>
<button class="btn btn-op" id="op-mul" onclick="inputOp('×')">×</button>
<button class="btn btn-num" onclick="inputNum('4')">4</button>
<button class="btn btn-num" onclick="inputNum('5')">5</button>
<button class="btn btn-num" onclick="inputNum('6')">6</button>
<button class="btn btn-op" id="op-sub" onclick="inputOp('−')">−</button>
<button class="btn btn-num" onclick="inputNum('1')">1</button>
<button class="btn btn-num" onclick="inputNum('2')">2</button>
<button class="btn btn-num" onclick="inputNum('3')">3</button>
<button class="btn btn-op" id="op-add" onclick="inputOp('+')">+</button>
<button class="btn btn-num btn-zero" onclick="inputNum('0')">0</button>
<button class="btn btn-num" onclick="inputDot()">.</button>
<button class="btn btn-eq" onclick="calculate()">=</button>
</div>
</div>

<script>
let currentInput='0';
let previousValue=null;
let operator=null;
let shouldResetInput=false;
let history=[];
let runningTotal=0;
let expressionStr='';

const displayEl=document.getElementById('display');
const exprEl=document.getElementById('expression');
const tapeEl=document.getElementById('tape');

function formatNumber(n){
if(n==='Error')return'Error';
let num=typeof n==='string'?parseFloat(n):n;
if(isNaN(num))return'0';
let s=num.toFixed(2);
let parts=s.split('.');
parts[0]=parts[0].replace(/\B(?=(\d{3})+(?!\d))/g,',');
return parts.join('.');
}

function updateDisplay(){
let val=currentInput;
if(val.length>12){
displayEl.classList.add('small');
}else{
displayEl.classList.remove('small');
}
if(val==='Error'){
displayEl.textContent='Error';
}else if(val.includes('.')&&val.endsWith('0')&&!shouldResetInput){
displayEl.textContent=val;
}else{
let n=parseFloat(val);
if(!isNaN(n)&&shouldResetInput){
displayEl.textContent=formatNumber(n);
}else{
displayEl.textContent=val;
}
}
exprEl.textContent=expressionStr;
highlightOp();
}

function highlightOp(){
document.querySelectorAll('.btn-op').forEach(b=>b.classList.remove('active'));
if(operator&&shouldResetInput){
let map={'+':'op-add','−':'op-sub','×':'op-mul','÷':'op-div'};
let el=document.getElementById(map[operator]);
if(el)el.classList.add('active');
}
}

function inputNum(n){
if(currentInput==='Error')currentInput='0';
if(shouldResetInput){
currentInput=n;
shouldResetInput=false;
}else{
if(currentInput==='0'&&n!=='0'){
currentInput=n;
}else if(currentInput==='0'&&n==='0'){
}else{
if(currentInput.replace(/[^0-9]/g,'').length>=12)return;
currentInput+=n;
}
}
updateDisplay();
}

function inputDot(){
if(shouldResetInput){
currentInput='0.';
shouldResetInput=false;
}else if(!currentInput.includes('.')){
currentInput+='.';
}
updateDisplay();
}

function inputOp(op){
if(currentInput==='Error')return;
let cur=parseFloat(currentInput);
if(previousValue!==null&&!shouldResetInput){
let result=compute(previousValue,cur,operator);
if(result==='Error'){
currentInput='Error';
previousValue=null;
operator=null;
expressionStr='';
updateDisplay();
return;
}
currentInput=String(result);
previousValue=result;
expressionStr=formatNumber(result)+' '+op;
}else{
previousValue=cur;
expressionStr=formatNumber(cur)+' '+op;
}
operator=op;
shouldResetInput=true;
updateDisplay();
}

function compute(a,b,op){
switch(op){
case'+':return a+b;
case'−':return a-b;
case'×':return a*b;
case'÷':return b===0?'Error':a/b;
default:return b;
}
}

function calculate(){
if(currentInput==='Error')return;
if(previousValue===null||operator===null)return;
let cur=parseFloat(currentInput);
let result=compute(previousValue,cur,operator);
let fullExpr=formatNumber(previousValue)+' '+operator+' '+formatNumber(cur);
if(result==='Error'){
currentInput='Error';
expressionStr=fullExpr+' =';
previousValue=null;
operator=null;
shouldResetInput=true;
updateDisplay();
return;
}
let rounded=Math.round(result*100)/100;
addTapeEntry(fullExpr,rounded);
runningTotal+=rounded;
expressionStr=fullExpr+' =';
currentInput=String(rounded);
previousValue=null;
operator=null;
shouldResetInput=true;
updateDisplay();
renderTape();
}

function addTapeEntry(expr,result){
history.push({expr,result});
if(history.length>50)history.shift();
}

function renderTape(){
tapeEl.innerHTML='';
if(history.length===0){
tapeEl.innerHTML='<div class="empty-state"><svg width="32" height="32" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><rect x="4" y="2" width="16" height="20" rx="2"/><line x1="8" y1="7" x2="16" y2="7"/><line x1="8" y1="11" x2="16" y2="11"/><line x1="8" y1="15" x2="12" y2="15"/></svg><span>Your calculation tape will appear here</span></div>';
return;
}
history.forEach((item,i)=>{
let line=document.createElement('div');
line.className='tape-line';
let sign=item.result<0?'negative':'positive';
let prefix=item.result>=0?'+':'';
line.innerHTML=`<span class="tape-expr">${item.expr}</span><span class="tape-result ${sign}">${prefix}${formatNumber(item.result)}</span>`;
tapeEl.appendChild(line);
});
let divider=document.createElement('div');
divider.className='tape-divider';
tapeEl.appendChild(divider);
let totalLine=document.createElement('div');
totalLine.className='tape-total';
let tSign=runningTotal<0?'−':'';
totalLine.innerHTML=`<span>Total (${history.length} entries)</span><span>${tSign}${formatNumber(Math.abs(runningTotal))}</span>`;
tapeEl.appendChild(totalLine);
tapeEl.scrollTop=tapeEl.scrollHeight;
}

function inputClear(){
if(currentInput!=='0'&&currentInput!=='Error'&&!shouldResetInput){
currentInput='0';
}else{
currentInput='0';
previousValue=null;
operator=null;
expressionStr='';
shouldResetInput=false;
}
updateDisplay();
}

function clearAll(){
currentInput='0';
previousValue=null;
operator=null;
expressionStr='';
shouldResetInput=false;
history=[];
runningTotal=0;
updateDisplay();
renderTape();
}

function toggleSign(){
if(currentInput==='Error'||currentInput==='0')return;
if(currentInput.startsWith('-')){
currentInput=currentInput.slice(1);
}else{
currentInput='-'+currentInput;
}
updateDisplay();
}

function inputPercent(){
if(currentInput==='Error')return;
let val=parseFloat(currentInput)/100;
val=Math.round(val*10000)/10000;
currentInput=String(val);
shouldResetInput=true;
updateDisplay();
}

// Keyboard support
document.addEventListener('keydown',e=>{
if(e.key>='0'&&e.key<='9')inputNum(e.key);
else if(e.key==='.')inputDot();
else if(e.key==='+')inputOp('+');
else if(e.key==='-')inputOp('−');
else if(e.key==='*')inputOp('×');
else if(e.key==='/'){e.preventDefault();inputOp('÷');}
else if(e.key==='Enter'||e.key==='=')calculate();
else if(e.key==='Escape')inputClear();
else if(e.key==='Backspace'){
if(!shouldResetInput&&currentInput.length>1){
currentInput=currentInput.slice(0,-1);
}else{
currentInput='0';
}
updateDisplay();
}
else if(e.key==='%')inputPercent();
});

renderTape();
updateDisplay();
</script>
</body>
</html>
